s=[]
def add(id,title,lead,rows,deep,items,takeaway,interactive=False):s.append(slide(id,title,lead,rows,deep,items,takeaway,interactive))
pressures=[('Trust','ความไว้ใจ','A familiar name','ชื่อคนที่คุ้นเคย'),('Fear','ความกลัว','Your account will close','บัญชีจะถูกปิด'),('Urgency','ความเร่งด่วน','Do this immediately','ต้องทำเดี๋ยวนี้'),('Authority','อำนาจ','The CEO ordered it','CEO สั่งมา'),('Greed','ความโลภ','Claim a reward','รับรางวัล'),('Helpfulness','ความอยากช่วย','Help me fix the problem','ช่วยแก้ปัญหาให้หน่อย')]
add('slide-01-manipulation-and-request',p('Notice the action the caller wants you to take.','สังเกตว่าผู้ติดต่ออยากให้เราทำอะไร'),p('Social Engineering manipulates a decision through deception or psychological pressure.','Social Engineering ใช้การหลอกหรือแรงกดดันทางจิตวิทยาเพื่อชักจูงการตัดสินใจ'),[[p(a,b),p(c,d),p('A persuasion cue is a reason to verify, not proof by itself.','เป็นสัญญาณให้ตรวจสอบ ไม่ใช่หลักฐานตัดสินด้วยตัวเอง')]for a,b,c,d in pressures],p('Social Engineering uses psychological manipulation or deception to make a person act or reveal information. The source identifies Trust, Fear, Urgency, Authority, Greed and Helpfulness. An attacker may combine them, for example pretending to be IT and urgently requesting a password to prevent an account closure. Focus on the requested action and whether it follows an authorized process, rather than trusting a familiar name or a plausible story. A legitimate request can also be urgent, so the safe response is independent verification and appropriate reporting, not guessing from one cue.','Social Engineering ใช้การชักจูงทางจิตวิทยาหรือหลอกให้คนทำบางอย่างหรือเปิดเผยข้อมูล ต้นฉบับระบุ Trust, Fear, Urgency, Authority, Greed และ Helpfulness ผู้โจมตีอาจใช้ร่วมกัน เช่น แอบอ้างเป็น IT แล้วเร่งขอ Password เพื่อไม่ให้บัญชีถูกปิด ควรดูว่าต้องการให้เราทำอะไรและตรงกับขั้นตอนที่อนุมัติหรือไม่ แทนการเชื่อชื่อคุ้นหรือเรื่องที่ดูสมจริง คำขอจริงก็อาจเร่งด่วนได้ จึงควรตรวจผ่านช่องทางอิสระและรายงานตามเหมาะสม ไม่ตัดสินจากสัญญาณเดียว'),[p('Pressure can cross email, calls, texts or other channels.','แรงกดดันอาจมาทางอีเมล โทรศัพท์ ข้อความ หรือช่องทางอื่น'),p('A claimed title does not establish authority.','การอ้างตำแหน่งไม่ได้พิสูจน์อำนาจ'),p('Verify the requested action through an approved process.','ตรวจแนวทางที่ขอผ่านขั้นตอนที่อนุมัติ')],p('Pause the request; verify the identity and authority.','หยุดคำขอไว้ก่อน แล้วตรวจตัวตนกับอำนาจ'))
add('slide-02-phishing-targeting',p('Phishing can be broad or carefully targeted.','Phishing อาจหว่านกว้างหรือเจาะจงเป้าหมาย'),p('The target changes the name; the goal is still to influence an unsafe action.','ชื่อเรียกต่างตามเป้าหมาย แต่ยังมุ่งชักจูงให้ทำสิ่งที่ไม่ปลอดภัย'),[
[p('Phishing','Phishing'),p('Fraudulent messages','ข้อความหลอกลวง'),p('Trick someone into following links, opening attachments or revealing information.','หลอกให้ตามลิงก์ เปิดไฟล์แนบ หรือเปิดเผยข้อมูล')],
[p('Spear Phishing','Spear Phishing'),p('A specific person or organization','เจาะจงบุคคลหรือองค์กร'),p('Personalized details can make the request convincing; they do not prove legitimacy.','ข้อมูลเฉพาะทำให้น่าเชื่อ แต่ไม่ได้พิสูจน์ว่าเป็นคำขอจริง')],
[p('Whaling','Whaling'),p('A high-profile individual, such as an executive','เจาะจงบุคคลระดับสูง เช่น ผู้บริหาร'),p('Defined by a high-profile target, not merely a message pretending to come from a CEO.','ดูที่เป้าหมายเป็นบุคคลระดับสูง ไม่ใช่แค่ข้อความแอบอ้างว่ามาจาก CEO')]],p('Phishing messages try to induce unsafe clicks, attachment opening or disclosure. Spear Phishing is targeted at a particular person or organization. Whaling targets high-profile people such as executives. These descriptions can overlap: an executive-targeted email can be both spear phishing and whaling. Knowing a project name, colleague or customer does not authenticate the sender. Inspect the request and verify independently when it asks for sensitive data, credentials or an unusual action. Good spelling and a familiar logo are not evidence that the message is safe.','Phishing หลอกให้กดลิงก์ เปิดไฟล์ หรือเปิดเผยข้อมูล ส่วน Spear Phishing เจาะจงบุคคลหรือองค์กร และ Whaling เจาะจงบุคคลระดับสูง เช่น ผู้บริหาร คำเหล่านี้ซ้อนกันได้ อีเมลที่เล็งผู้บริหารอาจเป็นทั้ง Spear Phishing และ Whaling การรู้ชื่อโครงการ เพื่อนร่วมงาน หรือลูกค้าไม่ได้ยืนยันผู้ส่ง ต้องดูคำขอและตรวจผ่านช่องทางอิสระเมื่อขอข้อมูลอ่อนไหว Credential หรือการทำงานที่ผิดปกติ การสะกดถูกและมี Logo คุ้นไม่ใช่หลักฐานว่าข้อความปลอดภัย'),[p('Broad phishing need not be personalized.','Phishing แบบหว่านกว้างไม่จำเป็นต้องปรับเฉพาะคน'),p('Whaling describes the high-profile target.','Whaling ดูที่เป้าหมายเป็นบุคคลระดับสูง'),p('Several technique labels can describe one event.','เหตุเดียวอาจเข้าได้หลายชื่อเทคนิค')],p('Personal detail is not authentication.','ข้อมูลส่วนตัวที่ผู้ส่งรู้ไม่ใช่การยืนยันตัวตน'))
add('slide-03-channel-and-pretext',p('The channel and the story are different dimensions.','ช่องทางกับเรื่องที่สร้างขึ้นเป็นคนละมิติ'),p('A fabricated IT-support story can arrive by voice or text.','เรื่องปลอมว่าเป็น IT Support อาจมาทั้งเสียงและข้อความ'),[
[p('Vishing','Vishing'),p('Voice / telephone calls','เสียง / โทรศัพท์'),p('A familiar-sounding voice or caller ID does not independently verify identity.','เสียงคุ้นหรือ Caller ID ไม่ยืนยันตัวตนอย่างอิสระ')],
[p('Smishing','Smishing'),p('SMS / text messages','SMS / ข้อความโทรศัพท์'),p('Do not rely on a supplied link or number as the verification channel.','อย่าใช้ลิงก์หรือเบอร์ที่ส่งมาเป็นช่องทางยืนยัน')],
[p('Pretexting','Pretexting'),p('A fabricated situation to obtain information or action','สร้างสถานการณ์ปลอมเพื่อขอข้อมูลหรือให้ทำบางอย่าง'),p('The pretext can accompany phishing, vishing or smishing.','เรื่องปลอมอาจใช้ร่วมกับ Phishing, Vishing หรือ Smishing')]],p('Vishing describes a voice or telephone channel; Smishing describes SMS/text messages. Pretexting describes the fabricated situation, such as an alleged IT emergency, used to obtain information or persuade someone to act. A single call can therefore be both vishing and pretexting. The official Domain 2 AI guidance adds AI-escalated social engineering and phishing: convincing generated messages or imitated voices make appearance and familiarity insufficient checks. Employees do not need to diagnose whether AI was used. Verify the request through known organizational channels and report the concern using the established process.','Vishing อธิบายช่องทางเสียงหรือโทรศัพท์ ส่วน Smishing คือ SMS/ข้อความโทรศัพท์ Pretexting อธิบายสถานการณ์ที่สร้างปลอม เช่น เหตุฉุกเฉิน IT เพื่อขอข้อมูลหรือให้ลงมือ สายเดียวจึงเป็นทั้ง Vishing และ Pretexting ได้ แนวทาง AI ของ Domain 2 ฉบับทางการเสริมการรับมือ Social Engineering และ Phishing ที่ AI ช่วยยกระดับ ข้อความสมจริงหรือเสียงเลียนแบบทำให้ดูภายนอกและความคุ้นเคยไม่เพียงพอ พนักงานไม่จำเป็นต้องวิเคราะห์ว่าใช้ AI หรือไม่ ควรตรวจคำขอผ่านช่องทางองค์กรที่รู้จักและรายงานตามขั้นตอน'),[p('Channel labels do not replace checking the requested action.','ชื่อช่องทางไม่แทนการตรวจสิ่งที่ผู้ติดต่อขอ'),p('A pretext is the fabricated situation, not a separate communication medium.','Pretext คือเรื่องที่สร้างขึ้น ไม่ใช่สื่ออีกประเภท'),p('Do not treat a voice or polished writing as proof of identity.','อย่าใช้เสียงหรือภาษาที่เรียบร้อยเป็นหลักฐานตัวตน')],p('Verify independently, regardless of the channel.','ตรวจอย่างอิสระ ไม่ว่าจะมาช่องทางใด'))
add('slide-04-verify-and-report',p('Use a known channel, then report the concern.','ใช้ช่องทางที่รู้จัก แล้วรายงานข้อกังวล'),p('Do not let the suspicious message choose how you verify it.','อย่าให้ข้อความน่าสงสัยเป็นคนกำหนดช่องทางที่ใช้ตรวจสอบ'),[
[p('Pause','หยุดก่อน'),p('Do not follow the supplied link or disclose a secret','ไม่ตามลิงก์ที่ให้มาและไม่เปิดเผย Secret'),p('Avoid extending the interaction while checking.','หลีกเลี่ยงการคุยต่อขณะตรวจสอบ')],
[p('Verify','ตรวจสอบ'),p('Use the known help desk or an approved directory','ใช้ Help desk ที่รู้จักหรือ Directory ที่อนุมัติ'),p('Use contact details independent of the suspicious message.','ใช้ข้อมูลติดต่อที่ไม่ได้มาจากข้อความน่าสงสัย')],
[p('Report','รายงาน'),p('Follow the organizational reporting process','ทำตามขั้นตอนรายงานขององค์กร'),p('If you already clicked or disclosed information, promptly tell the responsible team what happened.','หากคลิกหรือเปิดเผยไปแล้ว ให้แจ้งทีมรับผิดชอบโดยเร็วว่าเกิดอะไรขึ้น')]],p('When a request is suspicious, stop the requested action and verify through contact details already known to be genuine, such as the organizational directory or help-desk portal. Do not use a number supplied by the suspicious message as proof. Follow the internal reporting process; if you clicked or disclosed information, say what happened promptly so responsible teams can assess containment and credential recovery. Do not investigate the attacker or improvise destructive cleanup. Official Domain 2 AI guidance includes tools assisting early identification/reporting and initial triage under established playbooks. An AI summary is assistance, not verified authority or permission to upload sensitive evidence to an unapproved service.','เมื่อคำขอน่าสงสัย ให้หยุดสิ่งที่ขอและตรวจจากข้อมูลติดต่อที่รู้ว่าเป็นของจริง เช่น Directory องค์กรหรือ Help-desk portal อย่าใช้เบอร์ที่อยู่ในข้อความนั้นเป็นหลักฐาน ทำตามขั้นตอนรายงานภายใน หากคลิกหรือส่งข้อมูลไปแล้วให้บอกสิ่งที่เกิดขึ้นโดยเร็ว เพื่อให้ทีมรับผิดชอบประเมินการควบคุมเหตุและกู้ Credential อย่าสืบผู้โจมตีหรือทำลายหลักฐานตามใจ แนวทาง AI ของ Domain 2 รวมเครื่องมือช่วยสังเกต รายงาน และ Triage เบื้องต้นตาม Playbook ที่กำหนด สรุปจาก AI เป็นเพียงตัวช่วย ไม่ใช่อำนาจที่ยืนยันแล้วหรือสิทธิ์ให้อัปโหลดหลักฐานอ่อนไหวไปบริการที่ไม่ได้อนุมัติ'),[p('Known contact details are independent of the suspect request.','ข้อมูลติดต่อที่รู้จักต้องแยกจากคำขอที่สงสัย'),p('Prompt honest reporting helps responders act sooner.','รายงานสุจริตอย่างรวดเร็วช่วยให้ทีมรับมือได้เร็ว'),p('Use approved tools and the established playbook.','ใช้เครื่องมือที่อนุมัติและ Playbook ที่กำหนด')],p('A report should reach the team that can respond.','รายงานควรถึงทีมที่ดำเนินการรับมือได้'))
add('slide-05-unique-protected-passwords',p('Do not let one stolen password open several accounts.','อย่าให้ Password ที่หลุดหนึ่งชุดเปิดได้หลายบัญชี'),p('Use strong, unique passwords and protect how they are stored and used.','ใช้ Password ที่แข็งแรงและไม่ซ้ำ พร้อมปกป้องการเก็บและการใช้'),[
[p('Unique','ไม่ซ้ำ'),p('Different passwords for different accounts','แต่ละบัญชีใช้ Password ต่างกัน'),p('Reused credentials can be tried against other services: credential stuffing.','Credential ที่ใช้ซ้ำอาจถูกนำไปลองกับบริการอื่น เรียกว่า Credential stuffing')],
[p('Protected','ปกป้องไว้'),p('Use an approved password manager where appropriate','ใช้ Password manager ที่อนุมัติเมื่อเหมาะสม'),p('Do not share passwords or leave them in unprotected notes.','ไม่แชร์ Password และไม่ทิ้งในโน้ตที่ไม่ป้องกัน')],
[p('Respond to compromise','รับมือเมื่อสงสัยว่าหลุด'),p('Report promptly and follow the recovery process','รายงานเร็วและทำตามขั้นตอนกู้บัญชี'),p('Avoid predictable personal information; use MFA where available.','หลีกเลี่ยงข้อมูลส่วนตัวที่เดาง่าย และใช้ MFA เมื่อมี')]],p('The lecture recommends strong, unique passwords, no reuse across applications, no sharing, avoiding predictable personal details, appropriate password-manager use, MFA and reporting suspected compromise. Reuse lets a password stolen from one service be tried elsewhere; a unique password limits that particular route but does not stop phishing or malware by itself. Follow the approved policy and protect recovery methods too. Supplementary current NIST guidance rejects arbitrary periodic password changes and composition rules, and calls for screening unacceptable/common/compromised choices. Evidence of compromise requires action. This does not create one universal length or rotation rule for every system.','คำบรรยายแนะนำ Password ที่แข็งแรงและไม่ซ้ำ ไม่ใช้ซ้ำข้ามระบบ ไม่แชร์ ไม่ใช้ข้อมูลส่วนตัวเดาง่าย ใช้ Password manager เมื่อเหมาะสม เปิด MFA และรายงานเมื่อสงสัย Credential หลุด การใช้ซ้ำทำให้รหัสที่หลุดจากบริการหนึ่งถูกนำไปลองอีกบริการ รหัสไม่ซ้ำจำกัดเส้นทางนี้แต่ไม่หยุด Phishing หรือ Malware ด้วยตัวเอง ต้องทำตามนโยบายและปกป้องวิธีกู้บัญชีด้วย แนวทาง NIST ปัจจุบันที่เสริมบทเรียนไม่สนับสนุนการบังคับเปลี่ยนตามรอบโดยไร้เหตุหรือกฎผสมตัวอักษร และให้ตรวจตัวเลือกที่พบบ่อยหรือหลุด เมื่อมีหลักฐานว่าถูกเปิดเผยต้องดำเนินการ ไม่ใช่ตั้งกฎความยาวหรือรอบเปลี่ยนเดียวให้ทุกระบบ'),[p('Unique passwords reduce cross-account reuse exposure.','Password ไม่ซ้ำลดความเสี่ยงจากใช้ซ้ำข้ามบัญชี'),p('Never send a password or OTP to an unsolicited requester.','ไม่ส่ง Password หรือ OTP ให้ผู้ที่ติดต่อมาขอโดยไม่คาดหมาย'),p('Report suspected compromise even if the account still works.','รายงานเมื่อสงสัยว่าหลุด แม้บัญชียังใช้ได้')],p('Unique, protected and recoverable through an approved process.','ไม่ซ้ำ ปกป้องไว้ และกู้ผ่านขั้นตอนที่อนุมัติ'))
controls=[('Establish authentication policies','กำหนดนโยบาย Authentication','Define approved methods and recovery','กำหนดวิธียืนยันและกู้บัญชีที่อนุมัติ'),('Protect stored credentials','ปกป้อง Credential ที่จัดเก็บ','Restrict access to credential stores','จำกัดสิทธิ์เข้าถึงแหล่งเก็บ Credential'),('Implement appropriate access controls','ใช้ Access controls ที่เหมาะสม','Limit access to authorized roles','จำกัดสิทธิ์ตามบทบาทที่อนุญาต'),('Monitor suspicious authentication activity','ติดตาม Authentication ที่ผิดปกติ','Investigate concerning login patterns','ตรวจรูปแบบ Login ที่น่ากังวล'),('Encourage phishing-resistant authentication where appropriate','ส่งเสริม Authentication ต้าน Phishing เมื่อเหมาะสม','Choose methods suited to the risk','เลือกวิธีให้เหมาะกับความเสี่ยง')]
add('slide-06-organizational-credential-protection',p('Password protection is also an organizational responsibility.','การปกป้อง Password เป็นหน้าที่องค์กรด้วย'),p('Policies, protected credential stores, access control and monitoring support the user.','นโยบาย แหล่งเก็บ Credential ที่ปกป้อง Access control และ Monitoring ช่วยสนับสนุนผู้ใช้'),[[p(a,b),p(c,d),p('An organizational control from the original password-protection source.','มาตรการองค์กรตามต้นฉบับ Password Protection')]for a,b,c,d in controls],p('The original password-protection slide assigns organizations five responsibilities: authentication policies, stored-credential protection, appropriate access controls, suspicious-authentication monitoring and phishing-resistant authentication where appropriate. These complement employee habits. For example, a policy identifies approved authentication and recovery methods; access controls limit who can reach credential stores; monitoring gives responders evidence about concerning sign-ins. A user cannot compensate for an exposed organizational credential store by choosing a unique password alone. Technical owners must implement protection appropriately and avoid storing retrievable plaintext passwords. Authentication success also does not automatically authorize access to every resource.','สไลด์ Password Protection มอบหน้าที่องค์กรห้าด้าน ได้แก่ นโยบาย Authentication การปกป้อง Credential ที่เก็บ Access control ที่เหมาะสม การติดตาม Authentication ผิดปกติ และวิธีต้าน Phishing เมื่อเหมาะสม สิ่งเหล่านี้เสริมพฤติกรรมพนักงาน เช่น นโยบายกำหนดวิธียืนยันและกู้บัญชี Access control จำกัดผู้เข้าถึงแหล่งเก็บ Credential และ Monitoring ให้หลักฐาน Login ที่น่ากังวล ผู้ใช้เลือกรหัสไม่ซ้ำอย่างเดียวชดเชยฐาน Credential ขององค์กรที่เปิดเผยไม่ได้ เจ้าของระบบต้องป้องกันอย่างเหมาะสมและไม่เก็บ Password แบบ Plaintext ที่ดึงอ่านได้ อีกทั้งยืนยันตัวตนสำเร็จไม่ได้แปลว่ามีสิทธิ์เข้าถึงทุกทรัพยากร'),[p('Employees and system owners have complementary duties.','พนักงานกับเจ้าของระบบมีหน้าที่เสริมกัน'),p('Protect authentication and account-recovery processes.','ปกป้องทั้งการยืนยันและกู้บัญชี'),p('Monitoring requires responsible review and response.','Monitoring ต้องมีคนรับผิดชอบตรวจและตอบสนอง')],p('Safe habits need working organizational controls.','พฤติกรรมปลอดภัยต้องมีมาตรการองค์กรที่ทำงานได้'))
add('slide-07-mfa-and-phishing-resistance',p('MFA does not automatically mean phishing-resistant.','MFA ไม่ได้แปลว่าต้าน Phishing ได้โดยอัตโนมัติ'),p('Consider whether an attacker can relay the authenticator response to a real service.','พิจารณาว่าผู้โจมตีส่งต่อผล Authentication ไปใช้กับบริการจริงได้หรือไม่'),[
[p('Password + manually entered OTP','Password + OTP ที่กรอกเอง'),p('Adds an authentication factor','เพิ่มปัจจัยยืนยันตัวตน'),p('A fake site may relay the password and code.','เว็บปลอมอาจส่งต่อ Password กับรหัสได้')],
[p('Phishing-resistant authentication','Authentication ที่ต้าน Phishing'),p('Cryptographically binds the authentication to the verifier','ผูก Authentication กับ Verifier ด้วย Cryptography'),p('Properly implemented FIDO2/WebAuthn is an example; deployment and recovery still matter.','FIDO2/WebAuthn ที่ใช้ถูกต้องเป็นตัวอย่าง แต่การติดตั้งและกู้บัญชียังสำคัญ')]],p('MFA uses distinct authentication factors and can reduce the harm of a stolen password, but not every MFA method resists phishing. A manually entered OTP can be relayed through a fake site. NIST describes phishing resistance through cryptographic binding; FIDO2/WebAuthn provides verifier-name binding. Use approved authentication appropriate to the risk and protect recovery paths. Even phishing-resistant authentication does not prove that every request from an authenticated account is authorized or safe: account misuse, endpoint compromise and social engineering of non-login actions still need controls.','MFA ใช้ปัจจัยยืนยันตัวตนต่างประเภทและช่วยลดผลจาก Password หลุด แต่ไม่ใช่ทุกวิธีจะต้าน Phishing รหัส OTP ที่กรอกเองอาจถูกเว็บปลอมส่งต่อไปใช้ได้ NIST อธิบายการต้าน Phishing ด้วยการผูกผ่าน Cryptography โดย FIDO2/WebAuthn ผูกกับชื่อ Verifier ต้องใช้วิธีที่อนุมัติและเหมาะกับความเสี่ยง พร้อมปกป้องทางกู้บัญชี แม้ Authentication ต้าน Phishing ก็ไม่ได้พิสูจน์ว่าทุกคำขอจากบัญชีนั้นได้รับอนุญาตหรือปลอดภัย ยังต้องควบคุมการใช้บัญชีผิด เครื่องปลายทางถูกเจาะ และการหลอกให้ทำอย่างอื่นนอกการ Login'),[p('More factors and phishing resistance are different properties.','จำนวนปัจจัยกับการต้าน Phishing เป็นคุณสมบัติคนละอย่าง'),p('Do not approve unexpected authentication prompts.','ไม่อนุมัติคำขอ Authentication ที่ไม่คาดหมาย'),p('Follow the approved process to report a suspicious sign-in.','รายงาน Login น่าสงสัยตามขั้นตอนที่อนุมัติ')],p('Choose protection for the attack, not just a factor count.','เลือกการป้องกันให้ตรงการโจมตี ไม่ดูแค่จำนวนปัจจัย'))
rows=[
[p('A','A'),p('Give the caller the password and OTP to avoid disruption.','ให้ Password กับ OTP เพื่อไม่ให้งานหยุด'),p('Sharing secrets allows account misuse. Urgency and a claimed IT role are not proof of authorization.','การให้ Secret เปิดทางใช้บัญชีผิด ความเร่งด่วนกับการอ้างว่าเป็น IT ไม่พิสูจน์อำนาจ')],
[p('B','B'),p('Stop; verify through the known help desk and report the request.','หยุด ตรวจผ่าน Help desk ที่รู้จัก แล้วรายงานคำขอ'),p('Use contact details independent of the caller, protect secrets and follow the reporting playbook. If anything was disclosed, tell the team promptly.','ใช้ข้อมูลติดต่อที่ไม่มาจากผู้โทร ปกป้อง Secret และรายงานตาม Playbook หากเปิดเผยไปแล้วให้แจ้งทีมโดยเร็ว')],
[p('C','C'),p('Call back only the number the caller supplies.','โทรกลับเฉพาะเบอร์ที่ผู้โทรบอก'),p('A supplied number keeps verification under the requester’s control. Use a known independent contact.','เบอร์ที่ผู้โทรให้ยังอยู่ในอำนาจควบคุมของเขา ต้องใช้ผู้ติดต่ออิสระที่รู้จัก')],
[p('D','D'),p('Trust the familiar voice because the account has MFA.','เชื่อเสียงที่คุ้นเพราะบัญชีเปิด MFA แล้ว'),p('A voice can be impersonated, including with AI assistance. MFA does not authorize disclosure or make every method phishing-resistant.','เสียงถูกเลียนแบบได้รวมถึงใช้ AI ช่วย MFA ไม่ได้อนุญาตให้ส่ง Secret และไม่ใช่ทุกวิธีต้าน Phishing')]]
add('slide-08-urgent-it-caller-decision',p('An urgent “IT caller” asks for your password and OTP.','“เจ้าหน้าที่ IT” โทรเร่งขอ Password และ OTP'),p('The voice sounds familiar and claims the CEO needs a repair now. What should you do?','เสียงฟังคุ้นและอ้างว่า CEO ต้องการให้ซ่อมทันที ควรทำอย่างไร?'),rows,p('This authored scenario combines an IT-support pretext with voice delivery, authority and urgency. It is vishing and pretexting; it does not become legitimate because the voice is familiar or the account has MFA. The supported response is to stop, avoid disclosing secrets, verify through the genuine help desk and report according to the organizational playbook. Use an independently known contact rather than one supplied by the caller. If you already shared a secret or approved a prompt, explain that promptly so the responsible team can assess account recovery. The goal is a safer decision, not identifying the voice technology or investigating the caller yourself.','สถานการณ์แต่งนี้รวมเรื่องปลอม IT Support กับเสียง อำนาจ และความเร่งด่วน จึงเป็น Vishing ร่วมกับ Pretexting ไม่กลายเป็นคำขอจริงเพราะเสียงคุ้นหรือบัญชีมี MFA วิธีที่มีเหตุผลคือหยุด ไม่เปิดเผย Secret ตรวจผ่าน Help desk ของจริงและรายงานตาม Playbook ใช้ผู้ติดต่อที่รู้จักอย่างอิสระ ไม่ใช้เบอร์ที่ผู้โทรให้ หากส่ง Secret หรืออนุมัติคำขอไปแล้วให้บอกโดยเร็ว เพื่อให้ทีมรับผิดชอบประเมินการกู้บัญชี เป้าหมายคือการตัดสินใจปลอดภัย ไม่ใช่ตรวจว่าเลียนเสียงด้วยเทคโนโลยีใดหรือสืบผู้โทรเอง'),[p('Vishing is the voice channel; Pretexting is the fabricated support story.','Vishing คือช่องทางเสียง ส่วน Pretexting คือเรื่อง IT Support ที่สร้างขึ้น'),p('A known help-desk contact provides an independent verification route.','ผู้ติดต่อ Help desk ที่รู้จักเป็นทางตรวจที่อิสระ'),p('Reporting and recovery remain important after a mistake.','รายงานและกู้บัญชียังสำคัญหลังเกิดความผิดพลาด')],p('Protect secrets, verify independently and report promptly.','ปกป้อง Secret ตรวจอย่างอิสระ และรายงานเร็ว'),True)
l=lesson('lesson-d2-06-social-engineering-password-protection','2.3',p('Social Engineering & Password Protection','Social Engineering และการปกป้อง Password'),p('Recognize manipulation, distinguish source techniques and apply safe verification, reporting and credential protection.','รู้ทันการชักจูง แยกเทคนิคตามต้นฉบับ และใช้การตรวจ รายงาน กับปกป้อง Credential อย่างเหมาะสม'),[p('Distinguish six source techniques and the six persuasion pressures; verify and report suspicious requests.','แยกเทคนิคหกแบบกับแรงชักจูงหกด้าน และตรวจพร้อมรายงานคำขอน่าสงสัย'),p('Apply individual and organizational password protections and distinguish MFA from phishing resistance.','ใช้การป้องกัน Password ระดับบุคคล/องค์กร และแยก MFA จากการต้าน Phishing')],s,'Actual notes§§14–16, source S24–S27, summary social engineering/passwords, transcript end-user practices; official Domain2 AI impersonation and reporting/playbook supplement.',[{'id':'nist-sp-800-63b4','title':'NIST SP800-63B-4 — Digital Identity Guidelines: Authentication and Authenticator Management','authority':'technical-primary','url':'https://pages.nist.gov/800-63-4/sp800-63b.html','locator':'§3.1.1 password policy and§3.2.5 phishing resistance; current supplementary qualifications, not universal law.'},{'id':'ftc-phishing','title':'FTC — Recognize and Avoid Phishing Scams','authority':'technical-primary','url':'https://consumer.ftc.gov/articles/how-recognize-avoid-phishing-scams','locator':'Independent known contact rather than details in a suspicious message; organizational reporting remains internal.'}])
publish(l);wire('social-engineering-passwords-presentations','SocialPasswords','social-passwords');print('Authored/published eight bilingual L6 slides')
